// ❌ LEGACY REDUX (Requires manual action types, action creators, and pure switch statements)

// ✅ MODERN REDUX TOOLKIT (RTK)
import { createSlice } from '@reduxjs/toolkit';

const counterSlice = createSlice({
  name: 'counter',
  initialState: 0,
  reducers: {
    // Immer lets you "mutate" the state directly! No more {...state} spreading!
    increment: (state) => state + 1,
  },
});
